1	/* The design page's own rules: what the design system can't say. */
2	@scope (.design-page) {
3	  /* The page fills the workspace layout; the chat and the surface fill what
4	     the header leaves, and scroll inside themselves. */
5	  :scope { min-block-size: 0; }
6	  /* Never wrapped: a wrapped row grows to its content, so the panels would
7	     outgrow the window and the window would scroll. Side by side, the chat
8	     keeps its width and the surface takes the rest; in a narrow window they
9	     stack, sharing the height. */
10	  .workspace { flex: 1; min-block-size: 0; flex-wrap: nowrap; }
11	  .workspace > .chat { flex: 0 1 var(--side); }
12	  .workspace > .design { flex: 1 1 0; min-inline-size: 0; }
13	  @container (width < 52rem) {
14	    .workspace { flex-direction: column; }
15	    .workspace > .chat { flex: 2 1 0; }
16	    .workspace > .design { flex: 3 1 0; }
17	  }
18	  /* The pop-out: the surface fills the window. The page is the scope's root
19	     itself, so it's named with :scope; a bare .window-page would have to be
20	     inside .design-page and never match. */
21	  :scope.window-page > .design { flex: 1; }
